dave: Python sketch for docs (shortened):

```python
# sync helper with retries
import time, requests

def retry_get(url, attempts=3, base=0.2):
    for i in range(attempts):
        try:
            return requests.get(url, stream=True, timeout=10)
        except requests.RequestException:
            if i == attempts - 1:
                raise
            time.sleep(base * (2 ** i))

# async resume generator (conceptual)
import asyncio
async def async_stream_resume(call, max_retries=4):
    delay = 0.1
    for attempt in range(max_retries):
        try:
            async for chunk in call():
                yield chunk
            return
        except TransientError:
            await asyncio.sleep(delay)
            delay = min(delay * 2, 1.6)
    raise RuntimeError('stream failed')
```

